      SUBROUTINE PUNCH2CC     PUNCHES SECOND-ORDER TRANSFER MATRIX ELEMENTS ONTO "CARDS"CC ----------------------------------------------------------------------      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'TS.CIN'CC     LOCAL VARIABLESC      REAL            OUTPUT(30)C ---------------------------------------------------------------------C      IF (CDB .LT. 31) GO TO 13      N = CDB - 30      GO TO 20   13 N = 0   14 N = N + 1   20 JK = 0      DO 22 J = 1, 6      DO 21 K = 1, J      JK = JK + 1      OUTPUT(K) = TS(N,JK)*UBEAM(J)*UBEAM(K)/UBEAM(N)   21 CONTINUE      WRITE (NPUNCH,1009) N, J, (OUTPUT(K), K = 1, J) 1009 FORMAT (7H SECOND, I3, I2,6(1PE11.3))   22 CONTINUE      IF (CDB .GT. 30) GO TO 31      IF (CDB .NE. 30) GO TO 30      IF (N .GE. 5) GO TO 31      GO TO 14   30 IF (N .EQ. 3) GO TO 31      N = 3      GO TO 20   31 RETURN      END